/**
 * Photograph galleries, by peak.
 *
 * Five or more per mountain where Commons has them — 48 of the 51 do. The three
 * that do not (Muztagh Tower, Himlung Himal, Dykh-Tau) show what exists rather
 * than being padded out with the valley next door: a gallery of the wrong
 * mountain is worse than a short one.
 *
 * ONE OF THOSE THREE WAS A NEAR MISS WORTH RECORDING. Himlung Himal's Wikidata
 * item points at Commons Category:Nemjung — a different 7,000 m peak — so the
 * category sweep returned three photographs of the wrong mountain. They were
 * discarded and it was searched by name instead. Anything sourced by following
 * an identifier needs a second check that the identifier points where it says.
 *
 * CREDITS ARE MANDATORY. These are other people's photographs under CC BY and
 * CC BY-SA; the licences require the author named wherever the work appears, so
 * every image carries its photographer and a link to its Commons page.
 *
 * Regenerate with scratchpad/gallery.mjs, topup.mjs and dl-gallery.mjs.
 */

export interface GalleryPhoto {
  src: string;
  credit: string | null;
  license: string;
  pageUrl: string;
}

